16	
17	    private IdentityKeys() {
18	    }
19	
20	    /**
21	     * Derive the identity key into which all duplicate detection is consolidated: the full lower-case
22	     * hex SHA-256 over {@code (telephone or empty) + '|' + lowerEmail + '|' + soundex(lastName)}. A
23	     * null email or last name contributes an empty segment.
24	     */
25	    public static String identityKey(String telephone, String email, String lastName) {
26	        String raw = (telephone == null ? "" : telephone)
27	            + "|" + (email == null ? "" : email.toLowerCase())
28	            + "|" + soundex(lastName);
29	        return sha256Hex(raw);
30	    }
31	
32	    /**
33	     * American Soundex code of {@code value}: the retained first letter followed by up to three
34	     * digits, zero-padded to length four. Letters map to digits (b,f,p,v-&gt;1; c,g,j,k,q,s,x,z-&gt;2;
35	     * d,t-&gt;3; l-&gt;4; m,n-&gt;5; r-&gt;6); adjacent letters with the same code (and letters
36	     * separated only by h or w) collapse to one digit, while a vowel between them keeps both. Returns
37	     * an empty string when {@code value} contains no letters.
38	     */
39	    public static String soundex(String value) {
40	        if (value == null) {
41	            return "";
42	        }
43	        StringBuilder letters = new StringBuilder();
44	        for (char c : value.toUpperCase().toCharArray()) {
45	            if (c >= 'A' && c <= 'Z') {
46	                letters.append(c);
47	            }
48	        }
49	        if (letters.length() == 0) {
50	            return "";
51	        }
52	        StringBuilder code = new StringBuilder();
53	        code.append(letters.charAt(0));
54	        char prev = soundexDigit(letters.charAt(0));
55	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
56	            char c = letters.charAt(i);
57	            if (c == 'H' || c == 'W') {
58	                continue;
59	            }
60	            char digit = soundexDigit(c);
61	            if (digit != '0' && digit != prev) {
62	                code.append(digit);
63	            }
64	            prev = (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y') ? '0' : digit;
65	        }
66	        while (code.length() < 4) {
67	            code.append('0');
68	        }
69	        return code.substring(0, 4);
70	    }
71	
72	    /**
73	     * Map a single upper-case letter to its Soundex digit, or {@code '0'} for letters that are not
74	     * coded (a, e, i, o, u, y, h, w).
75	     */
76	    private static char soundexDigit(char c) {
77	        return switch (c) {
78	            case 'B', 'F', 'P', 'V' -> '1';
79	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
80	            case 'D', 'T' -> '3';
81	            case 'L' -> '4';
82	            case 'M', 'N' -> '5';
83	            case 'R' -> '6';
84	            default -> '0';
85	        };
86	    }
87	
88	    /**
89	     * Full lower-case hex SHA-256 of the UTF-8 bytes of {@code input}.
90	     */
91	    private static String sha256Hex(String input) {
92	        try {
93	            byte[] digest = MessageDigest.getInstance("SHA-256")
94	                .digest(input.getBytes(StandardCharsets.UTF_8));
95	            StringBuilder sb = new StringBuilder(digest.length * 2);
96	            for (byte b : digest) {
97	                sb.append(String.format("%02x", b));
98	            }
99	            return sb.toString();
100	        }
