1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "telephoneDisplay",
27	        expression = "java(telephoneDisplay(owner))")
28	    @Mapping(target = "membershipPoints",
29	        expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel",
31	        expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality",
33	        expression = "java(locality(owner))")
34	    @Mapping(target = "timezone",
35	        expression = "java(timezone(owner))")
36	    @Mapping(target = "contactPreference",
37	        expression = "java(contactPreference(owner))")
38	    @Mapping(target = "identityKey",
39	        expression = "java(identityKey(owner))")
40	    @Mapping(target = "ageBand",
41	        expression = "java(ageBand(owner))")
42	    @Mapping(target = "fiscalYear",
43	        expression = "java(fiscalYear(owner))")
44	    @Mapping(target = "salutation",
45	        expression = "java(salutation(owner))")
46	    @Mapping(target = "selfLink",
47	        expression = "java(selfLink(owner))")
48	    @Mapping(target = "ownerSegment",
49	        expression = "java(ownerSegment(owner))")
50	    @Mapping(target = "riskFlag",
51	        expression = "java(riskFlag(owner))")
52	    @Mapping(target = "sharesHousehold", ignore = true)
53	    OwnerDto toOwnerDto(Owner owner);
54	
55	    /**
56	     * Substrings that mark an email domain as "disposable-adjacent": a domain that resembles a
57	     * throwaway/disposable mailbox provider without being on the hard disposable blocklist (which is
58	     * rejected outright when the owner is created, so it never reaches a stored owner). The tokens are
59	     * matched case-insensitively as a substring of the domain, so both a different-TLD variant of a
60	     * known disposable provider (e.g. 'mailinator.net') and a domain carrying a disposable signal
61	     * word (e.g. 'throwaway-inbox.io') are caught.
62	     */
63	    java.util.Set<String> DISPOSABLE_ADJACENT_TOKENS = java.util.Set.of(
64	        "mailinator", "tempmail", "temp-mail", "guerrillamail", "guerrilla",
65	        "throwaway", "throw-away", "disposable", "trashmail", "trash-mail",
66	        "yopmail", "10minutemail", "getnada", "fakemail", "fake-mail");
67	
68	    /**
69	     * Whether the owner's email domain is disposable-adjacent: its domain (the part after the last
70	     * '@', compared case-insensitively) contains any known disposable-provider token. Returns false
71	     * when the owner has no email or the address has no domain part.
72	     */
73	    default boolean emailDomainDisposableAdjacent(Owner owner) {
74	        String email = owner.getEmail();
75	        if (email == null) {
76	            return false;
77	        }
78	        int at = email.lastIndexOf('@');
79	        if (at < 0 || at == email.length() - 1) {
80	            return false;
81	        }
82	        String domain = email.substring(at + 1).toLowerCase();
83	        for (String token : DISPOSABLE_ADJACENT_TOKENS) {
84	            if (domain.contains(token)) {
85	                return true;
86	            }
87	        }
88	        return false;
89	    }
90	
91	    /**
92	     * Derive the owner's risk flag: true when any of these hold — the owner is a possible duplicate
93	     * ({@code possibleDuplicate}), the owner's email domain is disposable-adjacent
94	     * ({@link #emailDomainDisposableAdjacent(Owner)}), or the owner's city is over its soft capacity
95	     * (the per-city capacity warning applies, i.e. {@code capacityWarning} is set because the city
96	     * already held 40 or more owners when this owner was created). Otherwise false.
97	     */
98	    default Boolean riskFlag(Owner owner) {
99	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
100	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
101	        return possibleDuplicate || overSoftCapacity || emailDomainDisposableAdjacent(owner);
102	    }
103	
104	    /**
105	     * Build the owner's canonical self link: '/api/owners/' followed by the owner's id. Returns null
106	     * when the owner has no id so an unsaved owner serializes cleanly.
107	     */
108	    default String selfLink(Owner owner) {
109	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
110	    }
111	
112	    /**
113	     * The set of known regions treated as METRO when deriving an owner's segment area.
114	     */
115	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
116	
117	    /**
118	     * Derive the owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when
119	     * {@link #membershipLevel(Owner)} is 3 or more, otherwise 'STANDARD'. AREA is 'METRO' when the
120	     * {@link #locality(Owner)} is a known region (NSW, VIC or QLD), otherwise 'REGIONAL'.
121	     */
122	    default String ownerSegment(Owner owner) {
123	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
124	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
125	        return tier + "_" + area;
126	    }
127	
128	    /**
129	     * Build the owner's salutation: the honorific title followed by a single space and the last name
130	     * (e.g. 'DR Who') when a title is present, or just the last name when no title was supplied. A
131	     * blank title is treated as absent.
132	     */
133	    default String salutation(Owner owner) {
134	        String lastName = owner.getLastName();
135	        String title = owner.getTitle();
136	        if (title == null || title.trim().isEmpty()) {
137	            return lastName;
138	        }
139	        return title + " " + lastName;
140	    }
141	
142	    /**
143	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
144	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
145	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
146	     * so owners without a birth date serialize cleanly.
147	     */
148	    default String ageBand(Owner owner) {
149	        java.time.LocalDate birthDate = owner.getBirthDate();
150	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
151	        if (birthDate == null || registrationDate == null) {
152	            return null;
153	        }
154	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
155	        if (age < 18) {
156	            return "MINOR";
157	        }
158	        if (age < 65) {
159	            return "ADULT";
160	        }
161	        return "SENIOR";
162	    }
163	
164	    /**
165	     * The E.164 country calling codes whose split from the national number is recognised when
166	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
167	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
168	     */
169	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
170	
171	    /**
172	     * Format the stored E.164 telephone for humans: the '+' and country calling code, a space, then
173	     * the national digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The
174	     * country code is split off using the recognised calling codes; when none matches, a single-digit
175	     * code is assumed so the value is still rendered as '+&lt;code&gt; &lt;grouped national&gt;'.
176	     * Returns the stored value unchanged when it is null or not in E.164 form.
177	     */
178	    default String telephoneDisplay(Owner owner) {
179	        String telephone = owner.getTelephone();
180	        if (telephone == null || !telephone.startsWith("+")) {
181	            return telephone;
182	        }
183	        String digits = telephone.substring(1);
184	        if (!digits.matches("\\d+")) {
185	            return telephone;
186	        }
187	        String countryCode = digits.substring(0, 1);
188	        String national = digits.substring(1);
189	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
190	            String candidate = digits.substring(0, codeLength);
191	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
192	                countryCode = candidate;
193	                national = digits.substring(codeLength);
194	                break;
195	            }
196	        }
197	        StringBuilder grouped = new StringBuilder();
198	        for (int i = 0; i < national.length(); i++) {
199	            if (i > 0 && i % 3 == 0) {
200	                grouped.append(' ');
201	            }
202	            grouped.append(national.charAt(i));
203	        }
204	        return "+" + countryCode + " " + grouped;
205	    }
206	
207	    /**
208	     * Derive the owner's identity key, the single value into which all duplicate detection is
209	     * consolidated: the full lower-case hex SHA-256 over
210	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners are
211	     * duplicates only when their whole identity keys are equal. A null email or last name contributes
212	     * an empty segment.
213	     */
214	    default String identityKey(Owner owner) {
215	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
216	    }
217	
218	    /**
219	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
220	     * otherwise 'PHONE'.
221	     */
222	    default String contactPreference(Owner owner) {
223	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
224	        return hasEmail ? "EMAIL" : "PHONE";
225	    }
226	
227	    /**
228	     * The calendar year in which the fiscal year containing {@code date} starts. The fiscal year
229	     * starts on 1 July, so dates in July through December map to their own calendar year while
230	     * dates in January through June map to the previous calendar year.
231	     */
232	    static int fiscalYearStart(java.time.LocalDate date) {
233	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
234	            ? date.getYear() : date.getYear() - 1;
235	    }
236	
237	    /**
238	     * Derive the owner's fiscal year from the (business-day-adjusted) registrationDate, formatted
239	     * 'FY&lt;YY&gt;' where YY is the last two digits of the fiscal year's starting calendar year. The
240	     * fiscal year starts on 1 July. Returns null when no registrationDate is available so owners
241	     * without one serialize cleanly.
242	     */
243	    default String fiscalYear(Owner owner) {
244	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
245	        if (registrationDate == null) {
246	            return null;
247	        }
248	        return String.format("FY%02d", fiscalYearStart(registrationDate) % 100);
249	    }
250	
251	    /**
252	     * Compute the owner's membership points. Starts at 0; add 2 when an email address is present;
253	     * add 1 when the owner has no namesakes (namesakeCount is 0); add 2 for a household of 3 or more
254	     * (householdSize); add 3 for tenure of at least one elapsed fiscal year, measured as the number
255	     * of fiscal-year starts (1 July) between the registrationDate and the current date. Because a
256	     * newly created owner has zero elapsed fiscal years, a new owner never earns the tenure points.
257	     */
258	    default Integer membershipPoints(Owner owner) {
259	        int points = 0;
260	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
261	        if (hasEmail) {
262	            points += 2;
263	        }
264	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
265	        if (noNamesakes) {
266	            points += 1;
267	        }
268	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
269	            points += 2;
270	        }
271	        if (owner.getRegistrationDate() != null
272	                && fiscalYearStart(java.time.LocalDate.now())
273	                    - fiscalYearStart(owner.getRegistrationDate()) >= 1) {
274	            points += 3;
275	        }
276	        return points;
277	    }
278	
279	    /**
280	     * Determine the owner's numeric membership level, derived from membershipPoints: 1 for 0-1
281	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The points-derived
282	     * level is then capped by {@code membershipLevelCap} when one was assigned at creation: a new
283	     * owner's level may not exceed one above the highest level among their existing household
284	     * members. When no cap was assigned (no existing household member), the points-derived level is
285	     * returned unchanged.
286	     */
287	    default Integer membershipLevel(Owner owner) {
288	        int points = membershipPoints(owner);
289	        int level;
290	        if (points <= 1) {
291	            level = 1;
292	        } else if (points <= 3) {
293	            level = 2;
294	        } else if (points <= 5) {
295	            level = 3;
296	        } else {
297	            level = 4;
298	        }
299	        Integer cap = owner.getMembershipLevelCap();
300	        if (cap != null && level > cap) {
301	            level = cap;
302	        }
303	        return level;
304	    }
305	
306	    /**
307	     * The fixed city-to-region table used to derive an owner's locality when the postcode is absent
308	     * or falls in no known range.
309	     */
310	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
311	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
312	
313	    /**
314	     * Region -&gt; inclusive 4-digit postcode range {low, high}: NSW 2000-2099, VIC 3000-3099,
315	     * QLD 4000-4099.
316	     */
317	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
318	        "NSW", new int[] {2000, 2099},
319	        "VIC", new int[] {3000, 3099},
320	        "QLD", new int[] {4000, 4099});
321	
322	    /**
323	     * Derive the owner's locality (canonical region), preferring the postcode: look up the region by
324	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back to the
325	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is
326	     * absent or in no known range. Returns 'UNKNOWN' when neither source resolves a region.
327	     */
328	    default String locality(Owner owner) {
329	        String postcode = owner.getPostcode();
330	        if (postcode != null && postcode.matches("\\d{4}")) {
331	            int value = Integer.parseInt(postcode);
332	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
333	                int[] range = entry.getValue();
334	                if (value >= range[0] && value <= range[1]) {
335	                    return entry.getKey();
336	                }
337	            }
338	        }
339	        String city = owner.getCity();
340	        if (city == null) {
341	            return "UNKNOWN";
342	        }
343	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
344	    }
345	
346	    /**
347	     * The fixed region-to-timezone table used to derive an owner's timezone from its locality:
348	     * NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane.
349	     */
350	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
351	        "NSW", "Australia/Sydney",
